// ── Parse AI response ──────────────────────────────────────────────────────
const aiNode = $('🤖 AI: Generate Platform Content').first();
let ai = {};
try {
  ai = JSON.parse(aiNode.json.choices[0].message.content);
} catch (e) {
  throw new Error(
    '⚠️ Failed to parse OpenAI JSON response. ' +
    'Check your OpenAI credential and model availability. ' +
    'Raw response: ' + JSON.stringify(aiNode.json).substring(0, 500)
  );
}

// ── Validate required AI fields ───────────────────────────────────────────
const required = [
  'facebook_post_caption','facebook_reels_caption','facebook_story_text',
  'instagram_post_caption','instagram_reels_caption','instagram_story_text',
  'youtube_video_title','youtube_video_description','youtube_video_tags',
  'youtube_shorts_title','tiktok_video_caption','tiktok_story_text','hashtags'
];
for (const field of required) {
  if (!ai[field]) ai[field] = ai.facebook_post_caption || 'Check out this video!';
}
if (!Array.isArray(ai.youtube_video_tags)) ai.youtube_video_tags = ['video'];
if (!Array.isArray(ai.hashtags)) ai.hashtags = ['#video'];

// ── Get file metadata ──────────────────────────────────────────────────────
const fi = $('\u2699\ufe0f SET: Extract File Info').first().json;

// ── Return assembled item with binary from Download node ──────────────────
return {
  json: {
    ...ai,
    fileId:      fi.fileId,
    fileName:    fi.fileName,
    mimeType:    fi.mimeType   || 'video/mp4',
    fileSize:    fi.fileSize   || 0,
    publicUrl:   fi.publicUrl,
    shareUrl:    fi.shareUrl,
    description: fi.description,
    _processedAt: new Date().toISOString()
  },
  binary: $input.item.binary   // binary.data = downloaded video file
};

// Re-attach video binary and capture upload URL from Reels Init response
const initData = $json;
if (!initData.upload_url || !initData.video_id) {
  throw new Error('Facebook Reels Init failed. Response: ' + JSON.stringify(initData));
}
return {
  json: {
    uploadUrl: initData.upload_url,
    videoId:   initData.video_id,
    fileSize:  $('🧩 CODE: Assemble Final Data').first().json.fileSize
  },
  binary: $('🧩 CODE: Assemble Final Data').first().binary
};

const initData = $json;
if (!initData.upload_url || !initData.video_id) {
  throw new Error('Facebook Story Init failed. Response: ' + JSON.stringify(initData));
}
return {
  json: {
    uploadUrl: initData.upload_url,
    videoId:   initData.video_id,
    fileSize:  $('🧩 CODE: Assemble Final Data').first().json.fileSize
  },
  binary: $('🧩 CODE: Assemble Final Data').first().binary
};

// YouTube returns the resumable upload URL in the 'location' response header
const uploadUrl = ($json.headers || {}).location || ($json.headers || {}).Location;
if (!uploadUrl) {
  throw new Error(
    '⚠️ YouTube did not return a Location header. ' +
    'Verify YouTube OAuth2 credential has youtube.upload scope and API quota is available. ' +
    'Response headers: ' + JSON.stringify(($json || {}).headers)
  );
}
return {
  json: {
    uploadUrl,
    mimeType: $('🧩 CODE: Assemble Final Data').first().json.mimeType || 'video/mp4'
  },
  binary: $('🧩 CODE: Assemble Final Data').first().binary
};

